CREATE TRIGGER
  listing_avionics_authorizations_invalidate_capture_delete
AFTER DELETE ON plugin_submissions
FOR EACH ROW
EXECUTE FUNCTION invalidate_listing_avionics_authorization_for_capture();

DROP TRIGGER IF EXISTS
