CREATE OR REPLACE FUNCTION validate_aircraft_reference_version_insert()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.publication_state <> 'building' THEN
    RAISE EXCEPTION 'reference profile versions must be assembled in building state';
  END IF;
  IF NEW.supersedes_version_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM aircraft_reference_configuration_versions previous
    WHERE previous.id = NEW.supersedes_version_id
      AND previous.aircraft_reference_configuration_id = NEW.aircraft_reference_configuration_id
      AND previous.model_year = NEW.model_year
      AND previous.publication_state = 'published'
  ) THEN
    RAISE EXCEPTION 'reference profile predecessor must be a published version of the same configuration/year';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS aircraft_reference_versions_validate_insert ON aircraft_reference_configuration_versions;
CREATE TRIGGER aircraft_reference_versions_validate_insert
BEFORE INSERT ON aircraft_reference_configuration_versions
FOR EACH ROW EXECUTE FUNCTION validate_aircraft_reference_version_insert();

CREATE OR REPLACE FUNCTION validate_aircraft_reference_child_insert()
RETURNS TRIGGER AS $$
DECLARE
  parent_state TEXT;
  parent_model_year BIGINT;
  expected_value_type TEXT;
BEGIN
  SELECT publication_state, model_year INTO parent_state, parent_model_year
  FROM aircraft_reference_configuration_versions
  WHERE id = NEW.aircraft_reference_configuration_version_id;
  IF parent_state IS DISTINCT FROM 'building' THEN
    RAISE EXCEPTION 'reference profile children require a building version';
  END IF;

  IF TG_TABLE_NAME = 'aircraft_reference_prices'
     AND NEW.evidence_kind = 'direct_model_year'
     AND NEW.price_reference_year <> parent_model_year THEN
    RAISE EXCEPTION 'direct model-year price must use the profile model year';
  ELSIF TG_TABLE_NAME = 'aircraft_reference_avionics' AND NOT EXISTS (
    SELECT 1 FROM avionics_models model
    WHERE model.id = NEW.avionics_model_id AND model.catalog_status = 'approved'
  ) THEN
    RAISE EXCEPTION 'reference avionics requires an approved catalog product';
  ELSIF TG_TABLE_NAME = 'aircraft_reference_engines' AND NOT EXISTS (
    SELECT 1 FROM aircraft_engine_catalog_models model
    WHERE model.id = NEW.aircraft_engine_catalog_model_id
      AND model.catalog_status = 'approved'
  ) THEN
    RAISE EXCEPTION 'reference engine requires an approved catalog model';
  ELSIF TG_TABLE_NAME = 'aircraft_reference_propellers' AND NOT EXISTS (
    SELECT 1 FROM aircraft_propeller_catalog_models model
    WHERE model.id = NEW.aircraft_propeller_catalog_model_id
      AND model.catalog_status = 'approved'
  ) THEN
    RAISE EXCEPTION 'reference propeller requires an approved catalog model';
  ELSIF TG_TABLE_NAME = 'aircraft_reference_features' THEN
    SELECT value_type INTO expected_value_type
    FROM aircraft_feature_definitions
    WHERE id = NEW.aircraft_feature_definition_id;
    IF (expected_value_type = 'boolean' AND NEW.boolean_value IS NULL)
       OR (expected_value_type = 'number' AND NEW.number_value IS NULL)
       OR (expected_value_type = 'text' AND NEW.text_value IS NULL)
       OR expected_value_type IS NULL THEN
      RAISE EXCEPTION 'reference feature value does not match its definition';
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS aircraft_reference_scope_building_insert ON aircraft_reference_applicability_scopes;
CREATE TRIGGER aircraft_reference_scope_building_insert
BEFORE INSERT ON aircraft_reference_applicability_scopes
FOR EACH ROW EXECUTE FUNCTION validate_aircraft_reference_child_insert();
