CREATE TRIGGER aircraft_reference_scope_immutable
BEFORE UPDATE OR DELETE ON aircraft_reference_applicability_scopes
FOR EACH ROW EXECUTE FUNCTION prevent_aircraft_reference_fact_mutation();
