CREATE OR REPLACE FUNCTION preserve_compatibility_projected_aircraft_entity()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $function$
DECLARE
  projection_exists BOOLEAN;
BEGIN
  EXECUTE format(
    'SELECT EXISTS (
       SELECT 1
       FROM aircraft_valuation_compatibility_projections
       WHERE %I = $1
     )',
    TG_ARGV[0]
  ) INTO projection_exists USING OLD.id;
  IF projection_exists THEN
    RAISE EXCEPTION 'compatibility-projected canonical aircraft hierarchy rows are immutable';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$;

