CREATE OR REPLACE FUNCTION preserve_compatibility_projected_aircraft_applicability()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'aircraft_generation_designations'
    AND EXISTS (
      SELECT 1
      FROM aircraft_valuation_compatibility_projections projection
      WHERE projection.aircraft_generation_id =
            OLD.aircraft_generation_id
        AND projection.aircraft_designation_id =
            OLD.aircraft_designation_id
    ) THEN
    RAISE EXCEPTION 'compatibility-projected generation applicability is immutable';
  END IF;
  IF TG_TABLE_NAME = 'aircraft_package_applicability'
    AND EXISTS (
      SELECT 1
      FROM aircraft_valuation_compatibility_projections projection
      WHERE projection.aircraft_factory_package_id =
            OLD.aircraft_factory_package_id
        AND projection.aircraft_designation_id =
            OLD.aircraft_designation_id
        AND (
          OLD.aircraft_generation_id IS NULL
          OR projection.aircraft_generation_id =
             OLD.aircraft_generation_id
        )
    ) THEN
    RAISE EXCEPTION 'compatibility-projected package applicability is immutable';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$;

