CREATE OR REPLACE FUNCTION require_guarded_listing_aircraft_projection_transition()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.aircraft_model_variant_id IS DISTINCT FROM
     OLD.aircraft_model_variant_id
    AND NOT EXISTS (
      SELECT 1
      FROM aircraft_valuation_projection_transitions transition
      JOIN aircraft_sale_listing_identity_assignments assignment
        ON assignment.id = transition.identity_assignment_id
       AND assignment.aircraft_sale_listing_id =
           transition.aircraft_sale_listing_id
      JOIN aircraft_valuation_compatibility_projections projection
        ON projection.aircraft_make_id = assignment.aircraft_make_id
       AND projection.aircraft_model_family_id =
           assignment.aircraft_model_family_id
       AND projection.aircraft_designation_id =
           assignment.aircraft_designation_id
       AND projection.aircraft_generation_id IS NOT DISTINCT FROM
           assignment.aircraft_generation_id
       AND projection.aircraft_factory_package_id IS NOT DISTINCT FROM
           assignment.aircraft_factory_package_id
      WHERE transition.aircraft_sale_listing_id = NEW.id
        AND projection.aircraft_model_variant_id =
            NEW.aircraft_model_variant_id
    ) THEN
    RAISE EXCEPTION 'listing aircraft compatibility FK may change only through an exact guarded transition';
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS listing_aircraft_projection_transition_update
  ON aircraft_sale_listings;
CREATE TRIGGER listing_aircraft_projection_transition_update
BEFORE UPDATE OF aircraft_model_variant_id ON aircraft_sale_listings
FOR EACH ROW
EXECUTE FUNCTION require_guarded_listing_aircraft_projection_transition();

CREATE OR REPLACE FUNCTION require_exact_projection_for_current_aircraft_identity()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM aircraft_sale_listings listing
    JOIN aircraft_valuation_projection_transitions transition
      ON transition.aircraft_sale_listing_id = listing.id
     AND transition.identity_assignment_id = NEW.identity_assignment_id
    JOIN aircraft_sale_listing_identity_assignments assignment
      ON assignment.id = NEW.identity_assignment_id
     AND assignment.aircraft_sale_listing_id =
         NEW.aircraft_sale_listing_id
    JOIN aircraft_valuation_compatibility_projections projection
      ON projection.aircraft_model_variant_id =
         listing.aircraft_model_variant_id
     AND projection.aircraft_make_id = assignment.aircraft_make_id
     AND projection.aircraft_model_family_id =
         assignment.aircraft_model_family_id
     AND projection.aircraft_designation_id =
         assignment.aircraft_designation_id
     AND projection.aircraft_generation_id IS NOT DISTINCT FROM
         assignment.aircraft_generation_id
     AND projection.aircraft_factory_package_id IS NOT DISTINCT FROM
         assignment.aircraft_factory_package_id
    WHERE listing.id = NEW.aircraft_sale_listing_id
  ) THEN
    RAISE EXCEPTION 'current aircraft identity requires the exact guarded listing projection';
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS listing_current_identity_projection_insert
  ON aircraft_sale_listing_current_identity_assignments;
CREATE TRIGGER listing_current_identity_projection_insert
BEFORE INSERT ON aircraft_sale_listing_current_identity_assignments
FOR EACH ROW
EXECUTE FUNCTION require_exact_projection_for_current_aircraft_identity();
DROP TRIGGER IF EXISTS listing_current_identity_projection_update
  ON aircraft_sale_listing_current_identity_assignments;
CREATE TRIGGER listing_current_identity_projection_update
BEFORE UPDATE OF identity_assignment_id
ON aircraft_sale_listing_current_identity_assignments
FOR EACH ROW
EXECUTE FUNCTION require_exact_projection_for_current_aircraft_identity();

CREATE OR REPLACE FUNCTION validate_aircraft_valuation_projection_transition_delete()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM aircraft_sale_listings listing
    JOIN aircraft_sale_listing_current_identity_assignments current_assignment
      ON current_assignment.aircraft_sale_listing_id = listing.id
     AND current_assignment.identity_assignment_id =
         OLD.identity_assignment_id
    JOIN aircraft_sale_listing_identity_assignments assignment
      ON assignment.id = current_assignment.identity_assignment_id
     AND assignment.aircraft_sale_listing_id = listing.id
    JOIN aircraft_valuation_compatibility_projections projection
      ON projection.aircraft_model_variant_id =
         listing.aircraft_model_variant_id
     AND projection.aircraft_make_id = assignment.aircraft_make_id
     AND projection.aircraft_model_family_id =
         assignment.aircraft_model_family_id
     AND projection.aircraft_designation_id =
         assignment.aircraft_designation_id
     AND projection.aircraft_generation_id IS NOT DISTINCT FROM
         assignment.aircraft_generation_id
     AND projection.aircraft_factory_package_id IS NOT DISTINCT FROM
         assignment.aircraft_factory_package_id
    WHERE listing.id = OLD.aircraft_sale_listing_id
  ) THEN
    RAISE EXCEPTION 'aircraft projection transition cannot close before exact pointer and listing projection';
  END IF;
  RETURN OLD;
END;
$function$;

DROP TRIGGER IF EXISTS aircraft_valuation_transition_validate_delete
  ON aircraft_valuation_projection_transitions;
CREATE TRIGGER aircraft_valuation_transition_validate_delete
BEFORE DELETE ON aircraft_valuation_projection_transitions
FOR EACH ROW
EXECUTE FUNCTION validate_aircraft_valuation_projection_transition_delete();

CREATE OR REPLACE VIEW aircraft_sale_listing_exact_compatibility_projections AS
SELECT
  listing.id AS listing_id,
  current_assignment.identity_assignment_id,
  listing.aircraft_model_variant_id,
  assignment.aircraft_make_id,
  assignment.aircraft_model_family_id,
  assignment.aircraft_designation_id,
  assignment.aircraft_generation_id,
  assignment.aircraft_factory_package_id
FROM aircraft_sale_listings listing
JOIN aircraft_sale_listing_current_identity_assignments current_assignment
  ON current_assignment.aircraft_sale_listing_id = listing.id
JOIN aircraft_sale_listing_identity_assignments assignment
  ON assignment.id = current_assignment.identity_assignment_id
 AND assignment.aircraft_sale_listing_id = listing.id
JOIN aircraft_valuation_compatibility_projections projection
  ON projection.aircraft_model_variant_id =
     listing.aircraft_model_variant_id
 AND projection.aircraft_make_id = assignment.aircraft_make_id
 AND projection.aircraft_model_family_id =
     assignment.aircraft_model_family_id
 AND projection.aircraft_designation_id =
     assignment.aircraft_designation_id
 AND projection.aircraft_generation_id IS NOT DISTINCT FROM
     assignment.aircraft_generation_id
 AND projection.aircraft_factory_package_id IS NOT DISTINCT FROM
     assignment.aircraft_factory_package_id;

-- Existing rows are not adopted or assigned mechanically. They remain as
-- evidence but cannot be valuation-ready without an exact curated projection.
UPDATE aircraft_sale_listings
SET ingestion_state = 'quarantined',
    ingestion_error =
      'aircraft compatibility projection migration: ready listing has no exact canonical projection',
    ingestion_completed_at = NULL,
    is_verified = FALSE,
    updated_at = CURRENT_TIMESTAMP
WHERE ingestion_state = 'ready'
  AND NOT EXISTS (
    SELECT 1
    FROM aircraft_sale_listing_exact_compatibility_projections exact_projection
    WHERE exact_projection.listing_id = aircraft_sale_listings.id
  );

CREATE OR REPLACE FUNCTION require_ready_listing_aircraft_projection()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.ingestion_state <> 'ready' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM aircraft_sale_listing_exact_compatibility_projections exact_projection
      WHERE exact_projection.listing_id = NEW.id
        AND exact_projection.aircraft_model_variant_id =
            NEW.aircraft_model_variant_id
    ) THEN
      RAISE EXCEPTION 'ready listing must first persist its exact canonical aircraft compatibility projection';
    END IF;
  ELSIF NOT EXISTS (
    SELECT 1
    FROM aircraft_sale_listing_current_identity_assignments current_assignment
    JOIN aircraft_sale_listing_identity_assignments assignment
      ON assignment.id = current_assignment.identity_assignment_id
     AND assignment.aircraft_sale_listing_id =
         current_assignment.aircraft_sale_listing_id
    JOIN aircraft_valuation_compatibility_projections projection
      ON projection.aircraft_model_variant_id =
         NEW.aircraft_model_variant_id
     AND projection.aircraft_make_id = assignment.aircraft_make_id
     AND projection.aircraft_model_family_id =
         assignment.aircraft_model_family_id
     AND projection.aircraft_designation_id =
         assignment.aircraft_designation_id
     AND projection.aircraft_generation_id IS NOT DISTINCT FROM
         assignment.aircraft_generation_id
     AND projection.aircraft_factory_package_id IS NOT DISTINCT FROM
         assignment.aircraft_factory_package_id
    WHERE current_assignment.aircraft_sale_listing_id = NEW.id
  ) THEN
    RAISE EXCEPTION 'ready listing requires its exact canonical aircraft compatibility projection';
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS listing_ready_requires_aircraft_projection
  ON aircraft_sale_listings;
CREATE TRIGGER listing_ready_requires_aircraft_projection
BEFORE UPDATE OF ingestion_state, aircraft_model_variant_id
ON aircraft_sale_listings
FOR EACH ROW
EXECUTE FUNCTION require_ready_listing_aircraft_projection();

DROP TRIGGER IF EXISTS listing_ready_insert_requires_aircraft_projection
  ON aircraft_sale_listings;
CREATE TRIGGER listing_ready_insert_requires_aircraft_projection
BEFORE INSERT ON aircraft_sale_listings
FOR EACH ROW
EXECUTE FUNCTION require_ready_listing_aircraft_projection();

CREATE OR REPLACE FUNCTION reject_ready_pending_aircraft_placeholder()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.ingestion_state = 'ready'
    AND EXISTS (
      SELECT 1
      FROM aircraft_sale_listing_pending_compatibility_placeholder placeholder
      WHERE placeholder.singleton_id = 1
        AND placeholder.aircraft_model_variant_id =
            NEW.aircraft_model_variant_id
    ) THEN
    RAISE EXCEPTION 'pending aircraft compatibility placeholder cannot become ready';
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS listing_ready_rejects_pending_aircraft_placeholder
  ON aircraft_sale_listings;
CREATE TRIGGER listing_ready_rejects_pending_aircraft_placeholder
BEFORE UPDATE OF ingestion_state, aircraft_model_variant_id
ON aircraft_sale_listings
FOR EACH ROW
EXECUTE FUNCTION reject_ready_pending_aircraft_placeholder();

CREATE OR REPLACE FUNCTION prevent_projected_aircraft_evidence_variant_move()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.aircraft_model_variant_id IS DISTINCT FROM
     OLD.aircraft_model_variant_id
    AND (
      EXISTS (
        SELECT 1
        FROM aircraft_valuation_compatibility_projections projection
        WHERE projection.aircraft_model_variant_id =
            OLD.aircraft_model_variant_id
      )
      OR EXISTS (
        SELECT 1
        FROM aircraft_valuation_compatibility_projections projection
        WHERE projection.aircraft_model_variant_id =
            NEW.aircraft_model_variant_id
      )
    ) THEN
    IF TG_TABLE_NAME = 'aircraft_model_spec_versions' THEN
      RAISE EXCEPTION 'aircraft spec evidence cannot move into or out of a projected variant';
    ELSIF TG_TABLE_NAME = 'aircraft_model_variant_price_points' THEN
      RAISE EXCEPTION 'aircraft price evidence cannot move into or out of a projected variant';
    ELSE
      RAISE EXCEPTION 'default avionics evidence cannot move into or out of a projected variant';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS projected_aircraft_spec_variant_move
  ON aircraft_model_spec_versions;
CREATE TRIGGER projected_aircraft_spec_variant_move
BEFORE UPDATE OF aircraft_model_variant_id ON aircraft_model_spec_versions
FOR EACH ROW
EXECUTE FUNCTION prevent_projected_aircraft_evidence_variant_move();
DROP TRIGGER IF EXISTS projected_aircraft_price_variant_move
  ON aircraft_model_variant_price_points;
CREATE TRIGGER projected_aircraft_price_variant_move
BEFORE UPDATE OF aircraft_model_variant_id
ON aircraft_model_variant_price_points
FOR EACH ROW
EXECUTE FUNCTION prevent_projected_aircraft_evidence_variant_move();
DROP TRIGGER IF EXISTS projected_aircraft_default_avionics_variant_move
  ON aircraft_model_variant_default_avionics;
CREATE TRIGGER projected_aircraft_default_avionics_variant_move
BEFORE UPDATE OF aircraft_model_variant_id
ON aircraft_model_variant_default_avionics
FOR EACH ROW
EXECUTE FUNCTION prevent_projected_aircraft_evidence_variant_move();

